{
  "name": "continual-learning",
  "version": "1.0.0",
  "description": "Incremental transcript-driven memory updates for AGENTS.md"
}

server {
    listen 80;
    server_name example.com;
    location / {
        proxy_pass http://backend_cluster;
    }
}

// Stitch MCP 서버 및 스킬 연동 설정 예시
{
  "mcpServers": {
    "stitch": {
      "command": "npx",
      "args": ["-y", "@google-labs/stitch-mcp"]
    }
  }
}

// MCP Server Integration Example
import { AutoClipMCP } from 'autoclip-mcp';
const client = new AutoClipMCP();
await client.clipVideo({ url: 'https://youtube.com/...', format: 'shorts' });

import { Plannotator } from 'plannotator';
// Start workspace inbox for AI agents
Plannotator.listen({ agent: 'claude-code' });

