import { NodAgent } from '@n8n/nod';

const agent = new NodAgent({ model: 'gpt-4o' });
await agent.run({ task: 'Cancel my unused streaming service trials' });

{
  "mcpServers": {
    "chrome-devtools": {
      "command": "npx",
      "args": ["-y", "chrome-devtools-mcp"]
    }
  }
}

import { AgUiProvider, useAgentState } from '@ag-ui/core';

function AgentWidget() {
  const { status, message } = useAgentState();
  return <div>Status: {status} - {message}</div>;
}

import { Button } from '@astryxdesign/core';

export default function App() {
  return <Button variant="primary">Generated with Agent</Button>;
}

import { Univer, UniverCorePreset } from '@univerjs/core';

const univer = new Univer({
  presets: [UniverCorePreset()]
});
univer.createUnit('sheet', {});

